import{_ as e,o as l,c as i,a5 as r}from"./chunks/framework.CvhCuK3c.js";const u=JSON.parse('{"title":"软件推荐","description":"","frontmatter":{},"headers":[],"relativePath":"android/software/index.md","filePath":"android/software/index.md"}'),o={name:"android/software/index.md"};function t(s,a,d,n,c,p){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="软件推荐" tabindex="-1">软件推荐 <a class="header-anchor" href="#软件推荐" aria-label="Permalink to “软件推荐”">​</a></h1><p>Android 实用开源软件推荐，按依赖层级排列：从底层 Root 到上层应用。</p><h2 id="root-方案" tabindex="-1">Root 方案 <a class="header-anchor" href="#root-方案" aria-label="Permalink to “Root 方案”">​</a></h2><h3 id="kernelsu" tabindex="-1">KernelSU <a class="header-anchor" href="#kernelsu" aria-label="Permalink to “KernelSU”">​</a></h3><p><a href="https://kernelsu.org/" target="_blank" rel="noreferrer">官网</a> · GPL-3.0</p><p>基于内核的 Android Root 权限方案，运行在 Linux 内核层，对用户空间拥有更强的控制力。</p><ul><li>仅授权应用可感知 <code>su</code>，其余应用完全无感知</li><li>可定制 Root 权限的 UID、GID、capabilities、SELinux 规则</li><li>模块系统支持无系统修改（systemless），通过 meta-overlayfs 启用模块挂载</li></ul><div class="tip custom-block"><p class="custom-block-title">适用人群</p><p>GKI 内核设备用户，看重隐蔽性与安全性。</p></div><h2 id="模块框架" tabindex="-1">模块框架 <a class="header-anchor" href="#模块框架" aria-label="Permalink to “模块框架”">​</a></h2><h3 id="lsposed" tabindex="-1">LSPosed <a class="header-anchor" href="#lsposed" aria-label="Permalink to “LSPosed”">​</a></h3><p><a href="https://github.com/lsposed/lsposed" target="_blank" rel="noreferrer">GitHub</a> · GPL-3.0</p><p>基于 LSPlant 的 ART 钩子框架，作为 Riru / Zygisk 模块运行，提供与经典 Xposed 一致的 API。</p><ul><li>兼容 Android 8.1 ~ 14</li><li>依赖 Magisk v24+，支持 Riru 和 Zygisk 两种载体</li><li>兼容经典 Xposed 模块生态，旧模块可直接运行</li><li>内置模块仓库，支持在应用内浏览和下载</li></ul><div class="tip custom-block"><p class="custom-block-title">适用人群</p><p>需要通过 Xposed 模块深度定制系统的用户。</p></div><h2 id="通话录音" tabindex="-1">通话录音 <a class="header-anchor" href="#通话录音" aria-label="Permalink to “通话录音”">​</a></h2><h3 id="cally" tabindex="-1">Cally <a class="header-anchor" href="#cally" aria-label="Permalink to “Cally”">​</a></h3><p><a href="https://github.com/LyoSU/cally" target="_blank" rel="noreferrer">GitHub</a> · GPL-3.0</p><p>一款通过 Shizuku 实现通话录音的工具，<strong>无需 Root，无需解锁 Bootloader</strong>，专为 Pixel 6 及以上设备优化。</p><ul><li>双轨录音（上行 + 下行），内置五级回退策略，某路失败自动切换备用方案</li><li>Material 3 Expressive UI，跟随系统动态取色</li><li>零遥测，无任何分析 SDK，录音文件永不访问网络</li><li>可选云端转录，支持自托管 OpenAI 兼容端点</li><li>AIDL + Binder IPC 安全校验，防止其他 Shizuku 应用滥用</li></ul><div class="tip custom-block"><p class="custom-block-title">适用人群</p><p>追求隐私、不想解锁 Root 的 Pixel 用户。</p></div><h3 id="bcr-basic-call-recorder" tabindex="-1">BCR (Basic Call Recorder) <a class="header-anchor" href="#bcr-basic-call-recorder" aria-label="Permalink to “BCR (Basic Call Recorder)”">​</a></h3><p><a href="https://github.com/chenxiaolong/BCR" target="_blank" rel="noreferrer">GitHub</a> · GPL-3.0</p><p>一款面向 Root / 自定义固件设备的简单通话录音应用，安装即用，后台静默录制。</p><ul><li>支持 Android 9+，输出格式丰富（OGG/Opus、M4A/AAC、FLAC、WAV、AMR）</li><li>立体声录制，分离上下行声道</li><li>支持 Magisk 与 KernelSU 双 Root 方案</li><li>自动录制规则、快捷设置磁贴、可定制文件名模板</li><li><strong>无网络权限</strong>，不访问网络</li></ul><div class="tip custom-block"><p class="custom-block-title">适用人群</p><p>已 Root 或刷入自定义 ROM 的用户，追求简单可靠的自动录音方案。</p></div>',25)])])}const b=e(o,[["render",t]]);export{u as __pageData,b as default};
